        if(!user.admin)return json({error:'เฉพาะผู้ดูแลเท่านั้น'},403);
        if(!env.GOOGLE_CHAT_CLIENT_ID||!env.GOOGLE_CHAT_CLIENT_SECRET)return redirect('/?chat=unconfigured');
